  "entidades.json": "{\n  \"$comment\": \"Entidades federativas. `curp`: clave alfabética de 2 letras (posiciones 12-13 de la CURP, catálogo RENAPO; NE = nacido en el extranjero). `ine`: clave numérica de 2 dígitos usada en la clave de elector (posiciones 15-16) en orden alfabético oficial.\",\n  \"source\": [\n    \"RENAPO, Instructivo normativo para la asignación de la CURP (catálogo de entidades)\",\n    \"INE, estructura de la clave de elector\"\n  ],\n  \"curp\": {\n    \"AS\": \"Aguascalientes\",\n    \"BC\": \"Baja California\",\n    \"BS\": \"Baja California Sur\",\n    \"CC\": \"Campeche\",\n    \"CL\": \"Coahuila\",\n    \"CM\": \"Colima\",\n    \"CS\": \"Chiapas\",\n    \"CH\": \"Chihuahua\",\n    \"DF\": \"Ciudad de México\",\n    \"DG\": \"Durango\",\n    \"GT\": \"Guanajuato\",\n    \"GR\": \"Guerrero\",\n    \"HG\": \"Hidalgo\",\n    \"JC\": \"Jalisco\",\n    \"MC\": \"México\",\n    \"MN\": \"Michoacán\",\n    \"MS\": \"Morelos\",\n    \"NT\": \"Nayarit\",\n    \"NL\": \"Nuevo León\",\n    \"OC\": \"Oaxaca\",\n    \"PL\": \"Puebla\",\n    \"QT\": \"Querétaro\",\n    \"QR\": \"Quintana Roo\",\n    \"SP\": \"San Luis Potosí\",\n    \"SL\": \"Sinaloa\",\n    \"SR\": \"Sonora\",\n    \"TC\": \"Tabasco\",\n    \"TS\": \"Tamaulipas\",\n    \"TL\": \"Tlaxcala\",\n    \"VZ\": \"Veracruz\",\n    \"YN\": \"Yucatán\",\n    \"ZS\": \"Zacatecas\",\n    \"NE\": \"Nacido en el extranjero\"\n  },\n  \"ine\": {\n    \"01\": \"Aguascalientes\",\n    \"02\": \"Baja California\",\n    \"03\": \"Baja California Sur\",\n    \"04\": \"Campeche\",\n    \"05\": \"Coahuila\",\n    \"06\": \"Colima\",\n    \"07\": \"Chiapas\",\n    \"08\": \"Chihuahua\",\n    \"09\": \"Ciudad de México\",\n    \"10\": \"Durango\",\n    \"11\": \"Guanajuato\",\n    \"12\": \"Guerrero\",\n    \"13\": \"Hidalgo\",\n    \"14\": \"Jalisco\",\n    \"15\": \"México\",\n    \"16\": \"Michoacán\",\n    \"17\": \"Morelos\",\n    \"18\": \"Nayarit\",\n    \"19\": \"Nuevo León\",\n    \"20\": \"Oaxaca\",\n    \"21\": \"Puebla\",\n    \"22\": \"Querétaro\",\n    \"23\": \"Quintana Roo\",\n    \"24\": \"San Luis Potosí\",\n    \"25\": \"Sinaloa\",\n    \"26\": \"Sonora\",\n    \"27\": \"Tabasco\",\n    \"28\": \"Tamaulipas\",\n    \"29\": \"Tlaxcala\",\n    \"30\": \"Veracruz\",\n    \"31\": \"Yucatán\",\n    \"32\": \"Zacatecas\"\n  }\n}\n",
  "iin.json": "{\n  \"$comment\": \"Rangos IIN/BIN por marca (ISO/IEC 7812). `prefixes` = prefijos exactos; `ranges` = [desde, hasta] inclusivo comparando los primeros N dígitos. `lengths` = longitudes válidas del PAN. `testPans` = PAN públicos de prueba (Stripe/PayPal/Adyen) que NUNCA se reportan.\",\n  \"source\": [\n    \"ISO/IEC 7812-1 (estructura del PAN, dígito de control Luhn)\",\n    \"https://docs.stripe.com/testing (PAN de prueba)\",\n    \"Rangos públicos de Visa 4, Mastercard 51-55 y 2221-2720 (desde 2017), Amex 34/37, Discover 6011/644-649/65, JCB 3528-3589\"\n  ],\n  \"brands\": [\n    { \"brand\": \"visa\", \"prefixes\": [\"4\"], \"lengths\": [13, 16, 19] },\n    { \"brand\": \"mastercard\", \"ranges\": [[\"51\", \"55\"], [\"2221\", \"2720\"]], \"lengths\": [16] },\n    { \"brand\": \"amex\", \"prefixes\": [\"34\", \"37\"], \"lengths\": [15] },\n    { \"brand\": \"discover\", \"prefixes\": [\"6011\", \"65\"], \"ranges\": [[\"644\", \"649\"]], \"lengths\": [16, 17, 18, 19] },\n    { \"brand\": \"jcb\", \"ranges\": [[\"3528\", \"3589\"]], \"lengths\": [16, 17, 18, 19] },\n    { \"brand\": \"carnet\", \"ranges\": [[\"506199\", \"506499\"]], \"lengths\": [16], \"note\": \"Marca doméstica MX; rango público aproximado, marcado como incierto.\" }\n  ],\n  \"testPans\": [\n    \"4111111111111111\",\n    \"4012888888881881\",\n    \"4242424242424242\",\n    \"4000056655665556\",\n    \"4000000000000002\",\n    \"4000000000009995\",\n    \"4222222222222\",\n    \"5555555555554444\",\n    \"5200828282828210\",\n    \"5105105105105100\",\n    \"2223003122003222\",\n    \"378282246310005\",\n    \"371449635398431\",\n    \"378734493671000\",\n    \"6011111111111117\",\n    \"6011000990139424\",\n    \"3566002020360505\",\n    \"3530111333300000\"\n  ]\n}\n",
